/**
 * The pancreatic cancer roadmap and the open questions (ideas) for the September 2026 deep dive. Every dated claim
 * in the steps points at a paper record in the pancreatic-evidence files or in the wider corpus, or at a
 * ClinicalTrials.gov record; the `watch` dates are quoted from the registry as read on 2026-09-24 and are not
 * predictions. The id carries the `-roadmap` suffix because `pancreatic` is the cancer record and ids are global;
 * the KRAS roadmap (../roadmaps.ts) and the early detection roadmap are the cross-cancer routes this one joins.
 */
type R = Omit<RoadmapInput, "kind" | "asOf">;
const r = (x: R): RoadmapInput => ({ kind: "roadmap", asOf, ...x });
type I = Omit<IdeaInput, "kind" | "asOf">;
const idea = (x: I): IdeaInput => ({ kind: "idea", asOf, tags: ["pancreatic-evidence"], ...x });

